// Composed from the shadcn/ui Date Picker recipe (MIT).
"use client";
import * as React from "react";
import { CalendarIcon } from "lucide-react";
import { Calendar } from "./calendar";
import { Button } from "./button";
import { Popover, PopoverTrigger, PopoverContent } from "./popover";
import "./date-picker.css";
export type DatePickerProps = {
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (value: Date | undefined) => void;
  label?: string;
  disabled?: boolean;
  placeholder?: string;
};
export function DatePicker(props: DatePickerProps) {
  const {
    value,
    defaultValue,
    onValueChange,
    label = "Choose date",
    disabled,
    placeholder = "Pick a date",
  } = props;
  const controlled = Object.prototype.hasOwnProperty.call(props, "value");
  const [local, setLocal] = React.useState(defaultValue);
  const [open, setOpen] = React.useState(false);
  const selected = controlled ? value : local;
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          disabled={disabled}
          aria-label={label}
          className="roc-date-picker-trigger"
        >
          <CalendarIcon />
          {selected
            ? new Intl.DateTimeFormat(undefined, {
                dateStyle: "medium",
              }).format(selected)
            : placeholder}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="roc-date-picker-popup" align="start">
        <Calendar
          mode="single"
          selected={selected}
          defaultMonth={selected}
          onSelect={(date) => {
            if (!controlled) setLocal(date);
            onValueChange?.(date);
            setOpen(false);
          }}
          autoFocus
        />
      </PopoverContent>
    </Popover>
  );
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt. Scoped CSS is precompiled.
"use client";
import * as React from "react";
import { cn } from "./utils";
import {
  ChevronDownIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
} from "lucide-react";
import {
  DayPicker,
  getDefaultClassNames,
  type DayButton,
} from "react-day-picker";
import { Button, buttonVariants } from "./button";
function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = "label",
  buttonVariant = "ghost",
  formatters,
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: React.ComponentProps<typeof Button>["variant"];
}) {
  const defaultClassNames = getDefaultClassNames();
  return (
    <DayPicker
      showOutsideDays={showOutsideDays}
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-group/calendar roc-u-bg-background roc-u-p-3 roc-u-[--cell-size:--spacing(8)] roc-u-[[data-slot=card-content]_&]:bg-transparent roc-u-[[data-slot=popover-content]_&]:bg-transparent",
          className,
        ),
      )}
      captionLayout={captionLayout}
      formatters={{
        formatMonthDropdown: (date) =>
          date.toLocaleString("default", { month: "short" }),
        ...formatters,
      }}
      classNames={{
        root: cn("roc-u-w-fit", defaultClassNames.root),
        months: cn(
          "roc-u-relative roc-u-flex roc-u-flex-col roc-u-gap-4 roc-u-md:flex-row",
          defaultClassNames.months,
        ),
        month: cn(
          "roc-u-flex roc-u-w-full roc-u-flex-col roc-u-gap-4",
          defaultClassNames.month,
        ),
        nav: cn(
          "roc-u-absolute roc-u-inset-x-0 roc-u-top-0 roc-u-flex roc-u-w-full roc-u-items-center roc-u-justify-between roc-u-gap-1",
          defaultClassNames.nav,
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant }),
          "roc-u-size-(--cell-size) roc-u-p-0 roc-u-select-none roc-u-aria-disabled:opacity-50",
          defaultClassNames.button_previous,
        ),
        button_next: cn(
          buttonVariants({ variant: buttonVariant }),
          "roc-u-size-(--cell-size) roc-u-p-0 roc-u-select-none roc-u-aria-disabled:opacity-50",
          defaultClassNames.button_next,
        ),
        month_caption: cn(
          "roc-u-flex roc-u-h-(--cell-size) roc-u-w-full roc-u-items-center roc-u-justify-center roc-u-px-(--cell-size)",
          defaultClassNames.month_caption,
        ),
        dropdowns: cn(
          "roc-u-flex roc-u-h-(--cell-size) roc-u-w-full roc-u-items-center roc-u-justify-center roc-u-gap-1.5 roc-u-text-sm roc-u-font-medium",
          defaultClassNames.dropdowns,
        ),
        dropdown_root: cn(
          "roc-u-relative roc-u-rounded-md roc-u-border roc-u-border-input roc-u-shadow-xs roc-u-has-focus:border-ring roc-u-has-focus:ring-[3px] roc-u-has-focus:ring-ring/50",
          defaultClassNames.dropdown_root,
        ),
        dropdown: cn(
          "roc-u-absolute roc-u-inset-0 roc-u-bg-popover roc-u-opacity-0",
          defaultClassNames.dropdown,
        ),
        caption_label: cn(
          "roc-u-font-medium roc-u-select-none",
          captionLayout === "label"
            ? "roc-u-text-sm"
            : "roc-u-flex roc-u-h-8 roc-u-items-center roc-u-gap-1 roc-u-rounded-md roc-u-pr-1 roc-u-pl-2 roc-u-text-sm roc-u-[&>svg]:size-3.5 roc-u-[&>svg]:text-muted-foreground",
          defaultClassNames.caption_label,
        ),
        month_grid: cn(
          "roc-u-w-full roc-u-border-collapse",
          defaultClassNames.month_grid,
        ),
        weekdays: cn("roc-u-flex", defaultClassNames.weekdays),
        weekday: cn(
          "roc-u-flex-1 roc-u-rounded-md roc-u-text-[0.8rem] roc-u-font-normal roc-u-text-muted-foreground roc-u-select-none",
          defaultClassNames.weekday,
        ),
        week: cn(
          "roc-u-mt-2 roc-u-flex roc-u-w-full",
          defaultClassNames.week,
        ),
        week_number_header: cn(
          "roc-u-w-(--cell-size) roc-u-select-none",
          defaultClassNames.week_number_header,
        ),
        week_number: cn(
          "roc-u-text-[0.8rem] roc-u-text-muted-foreground roc-u-select-none",
          defaultClassNames.week_number,
        ),
        day: cn(
          "roc-u-group/day roc-u-relative roc-u-aspect-square roc-u-h-full roc-u-w-full roc-u-p-0 roc-u-text-center roc-u-select-none roc-u-[&:last-child[data-selected=true]_button]:rounded-r-md",
          props.showWeekNumber ? "roc-u-[&:nth-child(2)[data-selected=true]_button]:rounded-l-md" : "roc-u-[&:first-child[data-selected=true]_button]:rounded-l-md",
          defaultClassNames.day,
        ),
        range_start: cn(
          "roc-u-rounded-l-md roc-u-bg-accent",
          defaultClassNames.range_start,
        ),
        range_middle: cn("roc-u-rounded-none", defaultClassNames.range_middle),
        range_end: cn(
          "roc-u-rounded-r-md roc-u-bg-accent",
          defaultClassNames.range_end,
        ),
        today: cn(
          "roc-u-rounded-md roc-u-bg-accent roc-u-text-accent-foreground roc-u-data-[selected=true]:rounded-none",
          defaultClassNames.today,
        ),
        outside: cn(
          "roc-u-text-muted-foreground roc-u-aria-selected:text-muted-foreground",
          defaultClassNames.outside,
        ),
        disabled: cn(
          "roc-u-text-muted-foreground roc-u-opacity-50",
          defaultClassNames.disabled,
        ),
        hidden: cn("roc-u-invisible", defaultClassNames.hidden),
        ...classNames,
      }}
      components={{
        Root: CalendarRoot,
        Chevron: CalendarChevron,
        DayButton: CalendarDayButton,
        WeekNumber: CalendarWeekNumber,
        ...components,
      }}
      {...props}
    />
  );
}
function CalendarDayButton({
  className,
  day,
  modifiers,
  ...props
}: React.ComponentProps<typeof DayButton>) {
  const defaultClassNames = getDefaultClassNames();
  const ref = React.useRef<HTMLButtonElement>(null);
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus();
  }, [modifiers.focused]);
  return (
    <Button
      ref={ref}
      variant="ghost"
      size="icon"
      data-day={day.date.toLocaleDateString()}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-flex roc-u-aspect-square roc-u-size-auto roc-u-w-full roc-u-min-w-(--cell-size) roc-u-flex-col roc-u-gap-1 roc-u-leading-none roc-u-font-normal roc-u-group-data-[focused=true]/day:relative roc-u-group-data-[focused=true]/day:z-10 roc-u-group-data-[focused=true]/day:border-ring roc-u-group-data-[focused=true]/day:ring-[3px] roc-u-group-data-[focused=true]/day:ring-ring/50 roc-u-data-[range-end=true]:rounded-md roc-u-data-[range-end=true]:rounded-r-md roc-u-data-[range-end=true]:bg-primary roc-u-data-[range-end=true]:text-primary-foreground roc-u-data-[range-middle=true]:rounded-none roc-u-data-[range-middle=true]:bg-accent roc-u-data-[range-middle=true]:text-accent-foreground roc-u-data-[range-start=true]:rounded-md roc-u-data-[range-start=true]:rounded-l-md roc-u-data-[range-start=true]:bg-primary roc-u-data-[range-start=true]:text-primary-foreground roc-u-data-[selected-single=true]:bg-primary roc-u-data-[selected-single=true]:text-primary-foreground roc-u-dark:hover:text-accent-foreground roc-u-[&>span]:text-xs roc-u-[&>span]:opacity-70",
          defaultClassNames.day,
          className,
        ),
      )}
      {...props}
    />
  );
}
export { Calendar, CalendarDayButton };

import "./calendar.css";

type CalendarComponents = NonNullable<
  React.ComponentProps<typeof DayPicker>["components"]
>;
const CalendarRoot: NonNullable<CalendarComponents["Root"]> = ({
  className,
  rootRef,
  ...props
}) => {
  return (
    <div
      data-slot="calendar"
      ref={rootRef}
      className={cn("roc-shadcn", cn(className))}
      {...props}
    />
  );
};
const CalendarChevron: NonNullable<CalendarComponents["Chevron"]> = ({
  className,
  orientation,
  ...props
}) => {
  if (orientation === "left") {
    return (
      <ChevronLeftIcon
        className={cn("roc-shadcn", cn("roc-u-size-4", className))}
        {...props}
      />
    );
  }
  if (orientation === "right") {
    return (
      <ChevronRightIcon
        className={cn("roc-shadcn", cn("roc-u-size-4", className))}
        {...props}
      />
    );
  }
  return (
    <ChevronDownIcon
      className={cn("roc-shadcn", cn("roc-u-size-4", className))}
      {...props}
    />
  );
};
const CalendarWeekNumber: NonNullable<CalendarComponents["WeekNumber"]> = ({
  children,
  ...props
}) => {
  return (
    <td {...props}>
      <div
        className={cn(
          "roc-shadcn",
          "roc-u-flex roc-u-size-(--cell-size) roc-u-items-center roc-u-justify-center roc-u-text-center",
        )}
      >
        {children}
      </div>
    </td>
  );
};

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Button as AnimatedButton } from "@animate-ui/react/primitives/buttons/button";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = AnimatedButton;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: var(--roc-space-2, 8px);
  min-height: var(--roc-control-height, 36px);
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-button-radius, var(--roc-radius-control));
  font-family: var(--roc-font-control, inherit);
  font-weight: var(--roc-weight-control, 500);
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
/* Keep the shared .roc-ui font reset from changing text button height. */
.roc-ui.roc-ui-button {
  line-height: 1.2;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
