import "./popover.css";

"use client";
// ROC primitive: an anchored popup. Behaviour from Base UI, shaped for ROC.
import * as React from "react";
import { Popover as Base } from "@animate-ui/react/primitives/base-ui/popover";
import {
  createContent,
  isNativeButton,
  renderChild,
} from "./primitive-popup";

const AnchorContext = React.createContext<{
  anchor: Element | null;
  setAnchor: (element: Element | null) => void;
}>({ anchor: null, setAnchor: () => {} });

type RootProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** `true` locks scroll and blocks outside pointer input. */
  modal?: boolean;
  children?: React.ReactNode;
};

function Root({ open, defaultOpen, onOpenChange, modal = false, children }: RootProps) {
  const [anchor, setAnchor] = React.useState<Element | null>(null);
  return (
    <AnchorContext.Provider value={{ anchor, setAnchor }}>
      <Base.Root
        open={open}
        defaultOpen={defaultOpen}
        modal={modal}
        onOpenChange={(next) => onOpenChange?.(next)}
      >
        {children}
      </Base.Root>
    </AnchorContext.Provider>
  );
}

type TriggerProps = React.ComponentProps<"button"> & { asChild?: boolean };

function Trigger({ asChild, children, ...props }: TriggerProps) {
  if (asChild && React.isValidElement(children)) {
    const child = children as React.ReactElement;
    return (
      <Base.Trigger
        {...(props as object)}
        nativeButton={isNativeButton(child)}
        render={renderChild(child, (state) => state.open)}
      />
    );
  }
  return (
    <Base.Trigger
      {...(props as object)}
      render={(triggerProps: Record<string, any>, state: { open: boolean }) => (
        <button {...triggerProps} data-state={state.open ? "open" : "closed"} />
      )}
    >
      {children}
    </Base.Trigger>
  );
}

/** Positions the popup against this element instead of the trigger. */
function Anchor({ asChild, children, ...props }: React.ComponentProps<"div"> & { asChild?: boolean }) {
  const { setAnchor } = React.useContext(AnchorContext);
  if (asChild && React.isValidElement(children)) {
    const child = children as React.ReactElement<{ ref?: React.Ref<Element> }>;
    return React.cloneElement(child, {
      ...(props as object),
      ref: (node: Element | null) => setAnchor(node),
    } as object);
  }
  return (
    <div {...props} ref={(node) => setAnchor(node)}>
      {children}
    </div>
  );
}

const BaseContent = createContent(
  { Positioner: Base.Positioner, Popup: Base.Popup },
  "popover",
);
function Content(props: React.ComponentProps<typeof BaseContent>) {
  const { anchor } = React.useContext(AnchorContext);
  return <BaseContent anchor={anchor} {...props} />;
}

function Close({ asChild, children, ...props }: TriggerProps) {
  if (asChild && React.isValidElement(children)) {
    const child = children as React.ReactElement;
    return (
      <Base.Close
        {...(props as object)}
        nativeButton={isNativeButton(child)}
        render={child}
      />
    );
  }
  return <Base.Close {...(props as object)}>{children}</Base.Close>;
}

export const Popover = { Root, Trigger, Anchor, Portal: Base.Portal, Content, Close };

"use client";
// ROC primitive: shared adapter that gives Base UI's Portal > Positioner > Popup
// parts the shape ROC components use: a single `Content`, `asChild` triggers,
// `data-state`, and the `--roc-popup-*` variables.
import * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { composeRefs } from "./primitive-utils";

export type Side = "top" | "right" | "bottom" | "left";
export type Align = "start" | "center" | "end";

export type PositionProps = {
  side?: Side;
  align?: Align;
  sideOffset?: number;
  alignOffset?: number;
  collisionPadding?: number;
  /** Set false to keep the popup on its requested side even when it overflows. */
  avoidCollisions?: boolean;
  /** Keep the popup in view while the trigger scrolls out ("always"). */
  sticky?: "partial" | "always";
};

/** Render `child` with Base UI's props merged in, plus `data-state`. */
export function renderChild(
  child: React.ReactElement,
  open: (state: any) => boolean,
  openValue = "open",
  extra?: (state: any) => Record<string, any>,
) {
  return (props: Record<string, any>, state: any) =>
    React.cloneElement(
      child,
      mergeProps(child.props as Record<string, any>, props, {
        "data-state": open(state) ? openValue : "closed",
        ...extra?.(state),
      }) as Record<string, any>,
    );
}

/** Triggers must opt out of native-button behaviour when they render something else. */
export const isNativeButton = (child: React.ReactElement) =>
  typeof child.type !== "string" || child.type === "button";

/** Base UI reports logical sides for submenus; ROC CSS and components use physical ones. */
export function physicalSide(side: string | undefined) {
  if (side !== "inline-start" && side !== "inline-end") return side;
  const rtl =
    typeof document !== "undefined" && document.documentElement.dir === "rtl";
  return (side === "inline-end") !== rtl ? "right" : "left";
}

/** A popup copies its own z-index to the positioner, so stacking matches the CSS. */
function useStackingOf(ref: React.RefObject<HTMLElement | null>) {
  const [zIndex, setZIndex] = React.useState<string>();
  React.useLayoutEffect(() => {
    if (!ref.current) return;
    const value = getComputedStyle(ref.current).zIndex;
    setZIndex(value === "auto" ? undefined : value);
  });
  return zIndex;
}

type Parts = { Positioner: React.ElementType; Popup: React.ElementType };

/**
 * Build a Content component. `prefix` names the CSS variables that ROC and shadcn CSS
 * reads (`--roc-<prefix>-content-transform-origin` and friends).
 */
export function createContent(parts: Parts, prefix: string, openValue = "open") {
  type Props = Omit<React.ComponentProps<"div">, "ref"> &
    PositionProps & {
      ref?: React.Ref<HTMLDivElement>;
      anchor?: Element | null;
      /** Extra props for Base UI's Positioner, such as `alignItemWithTrigger`. */
      positionerProps?: Record<string, unknown>;
      /** Keep mounted while closed. Not needed: Portal handles presence. */
      forceMount?: boolean;
    };
  return function Content({
    side,
    align,
    sideOffset,
    alignOffset,
    collisionPadding = 12,
    avoidCollisions = true,
    sticky,
    anchor,
    positionerProps,
    forceMount: _forceMount,
    style,
    ref,
    children,
    ...props
  }: Props) {
    const popup = React.useRef<HTMLDivElement | null>(null);
    const stacking = useStackingOf(popup);
    return (
      <parts.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        collisionPadding={collisionPadding}
        collisionAvoidance={
          avoidCollisions ? undefined : { side: "none", align: "none" }
        }
        sticky={sticky === "always"}
        anchor={anchor ?? undefined}
        {...positionerProps}
        style={{ zIndex: stacking }}
      >
        <parts.Popup
          data-roc-motion="animate-ui"
          {...props}
          ref={composeRefs(ref, popup)}
          render={(popupProps: Record<string, any>, state: { open: boolean }) => (
            <div
              {...popupProps}
              data-side={physicalSide(popupProps["data-side"])}
              data-state={state.open ? openValue : "closed"}
            />
          )}
          style={
            {
              [`--roc-${prefix}-content-transform-origin`]: "var(--transform-origin)",
              [`--roc-${prefix}-content-available-height`]: "var(--available-height)",
              [`--roc-${prefix}-content-available-width`]: "var(--available-width)",
              [`--roc-${prefix}-trigger-width`]: "var(--anchor-width)",
              [`--roc-${prefix}-trigger-height`]: "var(--anchor-height)",
              ...style,
            } as React.CSSProperties
          }
        >
          {children}
        </parts.Popup>
      </parts.Positioner>
    );
  };
}

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

